import { z } from 'zod';

import { /* PricingType, */ PRICING_MODELS, PRICING_TYPES } from '@shared/types/aiTool.types';

export const createAIToolInputSchema = z.object({
	name: z.string().min(1),
	description: z.string().optional(),
	tags: z.string().array().optional(),
	pricingType: z.enum(PRICING_TYPES),
	pricingModel: z.enum(PRICING_MODELS),
});

export type CreateAIToolInput = z.infer<typeof createAIToolInputSchema>;
